<multiRecordWidget>
    <description>A table widget for displaying multiple records in a structured format with rows and columns. Supports text cells and styled badge cells for status indicators.</description>
    <schema>
{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "required": ["cols", "rows"],
    "properties": {
        "id": {
            "type": "string",
            "description": "Optional submit identifier used when selectMode is multiSelect. Defaults to multi_record_selection."
        },
        "subtitle": {
            "type": "string",
            "description": "Optional description for the table (used for accessibility)"
        },
        "selectMode": {
            "type": "string",
            "enum": ["none", "multiSelect"],
            "description": "Optional row selection behavior. Use multiSelect to render a checkbox column and a submit button."
        },
        "multiSelectActionText": {
            "type": "string",
            "description": "Optional label for the multi-select submit button. Only used when selectMode is multiSelect."
        },
        "multiSelectMetadata": {
            "description": "Optional JSON value returned unchanged as metadata in the multi-select submit payload."
        },
        "cols": {
            "type": "array",
            "description": "Column headers for the table. Each column can be a string or an object with label and display options.",
            "items": {
                "oneOf": [
                    {
                        "type": "string",
                        "description": "Simple column header text"
                    },
                    {
                        "type": "object",
                        "required": ["label"],
                        "properties": {
                            "label": {
                                "type": "string",
                                "description": "Column header text"
                            },
                            "showOnExpand": {
                                "type": "boolean",
                                "description": "If true, this column is only visible when the widget is expanded/focused"
                            }
                        }
                    }
                ]
            }
        },
        "rows": {
            "type": "array",
            "description": "Table rows with cells and optional actions",
            "items": {
                "type": "object",
                "required": ["cells"],
                "properties": {
                    "cells": {
                        "type": "array",
                        "description": "Array of cells for this row",
                        "items": {
                            "oneOf": [
                                {
                                    "type": "string",
                                    "description": "Simple text cell"
                                },
                                {
                                    "type": "object",
                                    "required": ["type", "text", "priority"],
                                    "properties": {
                                        "type": {
                                            "type": "string",
                                            "enum": ["badge"],
                                            "description": "Indicates this is a badge cell"
                                        },
                                        "text": {
                                            "type": "string",
                                            "description": "Text to display in the badge"
                                        },
                                        "priority": {
                                            "type": "string",
                                            "enum": ["alert", "warning", "medium", "success", "neutral"],
                                            "description": "Visual styling for the badge (alert: red, warning: orange, medium: informational, success: green, neutral: gray)"
                                        }
                                    }
                                }
                            ]
                        }
                    },
                    "action": {
                        "type": "object",
                        "required": ["text", "command"],
                        "description": "Optional action button for this row",
                        "properties": {
                            "text": {
                                "type": "string",
                                "description": "Label displayed on the action button"
                            },
                            "command": {
                                "type": "string",
                                "description": "Command identifier to fire when the action is clicked"
                            }
                        }
                    },
                    "drillDownAction": {
                        "type": "string",
                        "description": "Command to fire when the first column is clicked. When specified, the first column becomes a clickable link."
                    }
                }
            }
        }
    }
}
    </schema>
    <translation_guidance>
When response-language translation is enabled, translate user-visible table text: subtitle, multiSelectActionText, column labels, natural-language string cells, badge text, and row action.text. Never translate JSON property names, id, selectMode enum values, multiSelectMetadata, badge type, badge priority enum values, action.command, drillDownAction, IDs, codes, dates, numbers, booleans, object keys, or source-system values. selectMode must remain exactly none or multiSelect, and badge type must remain badge.
    </translation_guidance>
    <instructions>
**Configuration Structure**

cols: Array of column headers. Each column can be either:
  - A simple string for the column header name
  - An object with:
    - label: The column header text
    - showOnExpand: Optional boolean. If true, this column is only visible when the widget is expanded/focused. Use this for secondary details that aren't essential in the compact view.

rows: Array of row objects. Each row is an object with:
  - cells: Array of cell values that correspond to the columns defined in cols. The number of cells should match the number of columns.
  - action: Optional object defining a clickable action button for this row with:
    - text: Label displayed on the button (e.g., "View", "Edit", "Delete")
    - command: Command string to execute when clicked (must use ora.Invoke() or ora.Agent() format)
  - drillDownAction: Optional command string. When specified, the first column becomes a clickable link that fires this command when clicked. Use this when you want users to drill down into details by clicking the primary identifier (e.g., Order ID, Transaction ID).

subtitle: Optional description for the table. This is hidden visually but provided to screen readers for accessibility. Use it to give context about what data the table contains.

id: Optional string identifier for the submit event. Only needed when selectMode is multiSelect. If omitted, the widget uses "multi_record_selection".

selectMode: Optional row selection mode.
  - "none" (default): behaves like the widget does today.
  - "multiSelect": shows a checkbox for each row and a submit button below the table.

multiSelectActionText: Optional button label used when selectMode is "multiSelect". Defaults to "Submit".

multiSelectMetadata: Optional JSON value returned unchanged as the top-level metadata property in the submit payload when selectMode is "multiSelect".

**IMPORTANT: Actions**
Only include action buttons or drillDownAction when explicitly prompted to do so. Do not make up actions or add them automatically. Actions should only be added when the user specifically requests actionable elements or when your prompting instructions explicitly tell you to include them.

**Multi-select submission**

When selectMode is "multiSelect", the widget submits the selected rows through:
- \`ora.Agent(<oraFormSubmit id="{id-or-multi_record_selection}">{"value":[{"id":"selectedRows","value":[...selected row objects...]}],"metadata":...}</oraFormSubmit>)\`

The selected rows are returned as row objects with \`cells\` and any existing \`action\` / \`drillDownAction\` fields preserved.

**Cell Types**

Each cell in a row's cells array can be one of two types:

1. **String Cell**: Simple text value
   - Just provide the string directly
   - Example: "TXN-1234", "$1,250.00", "2024-01-15"

2. **Badge Cell**: Highlighted status indicator with color coding
   - Must be an object with three properties:
     - type: Must be "badge"
     - text: The text to display in the badge (keep short, 1-3 words, usually ALL CAPS)
     - priority: One of five values that controls the color:
       - "alert" - Red background, use for critical/error states
       - "warning" - Orange background, use for warning/pending states
       - "medium" - Blue informational background, use for informational states
       - "success" - Green background, use for completed/successful states
       - "neutral" - Gray background, use for neutral states
   - Example: { "type": "badge", "text": "COMPLETED", "priority": "success" }

**Action Command Format**

When actions are included, the command must follow one of these standardized formats:
- ora.Invoke(command, context) - For application-level commands. The command is a string identifier and context is an optional object with parameters.
  - Example: ora.Invoke("viewTransaction", { "id": "TXN-1234" })
- ora.Agent(content) - For LLM/agent commands
  - Example: ora.Agent("show transaction details")

**Best Practices**

- Ensure all rows have the same number of cells as there are columns (including showOnExpand columns)
- Use badges for status fields, categories, or anything that benefits from visual highlighting
- Keep badge text short and clear (e.g., "ACTIVE", "PENDING", "FAILED", "HIGH", "LOW")
- Use ALL CAPS for badge text to make them stand out
- Choose priority levels that match the semantic meaning (don't use "success" for errors)
- Use subtitle to describe what the table shows for accessibility
- Keep table data scannable - avoid very long text in cells
- When actions are included, keep action button text short (1-2 words like "View", "Edit", "Delete")
- Use showOnExpand for secondary/detailed columns that aren't essential in the compact view (e.g., internal IDs, timestamps, metadata). Keep the most important columns always visible.
    </instructions>
    <examples>
// Example 1: Basic table (no actions)
{
    "subtitle": "Monthly sales",
    "cols": ["Region", "Revenue", "Growth"],
    "rows": [
        { "cells": ["North", "$45,000", "12%"] },
        { "cells": ["South", "$38,000", "8%"] }
    ]
}

// Example 2: Table with action button
{
    "subtitle": "Pending approvals",
    "cols": ["Request ID", "Type", "Status"],
    "rows": [
        {
            "cells": ["REQ-101", "Budget", { "type": "badge", "text": "PENDING", "priority": "warning" }],
            "action": { "text": "Review", "command": "ora.Invoke(\"reviewRequest\", { \"id\": \"REQ-101\" })" }
        },
        {
            "cells": ["REQ-102", "Travel", { "type": "badge", "text": "PENDING", "priority": "warning" }],
            "action": { "text": "Review", "command": "ora.Invoke(\"reviewRequest\", { \"id\": \"REQ-102\" })" }
        }
    ]
}

// Example 3: Table with drilldown links
{
    "subtitle": "Order summary",
    "cols": ["Order ID", "Customer", "Total", "Status"],
    "rows": [
        {
            "cells": ["ORD-5001", "Acme Corp", "$12,500", { "type": "badge", "text": "SHIPPED", "priority": "success" }],
            "drillDownAction": "ora.Invoke(\"viewOrder\", { \"id\": \"ORD-5001\" })"
        },
        {
            "cells": ["ORD-5002", "Global Inc", "$8,750", { "type": "badge", "text": "PROCESSING", "priority": "medium" }],
            "drillDownAction": "ora.Invoke(\"viewOrder\", { \"id\": \"ORD-5002\" })"
        }
    ]
}

// Example 4: Table with both drilldown and action
{
    "subtitle": "Active issues",
    "cols": ["Issue ID", "Summary", "Priority"],
    "rows": [
        {
            "cells": ["ISS-301", "Login timeout", { "type": "badge", "text": "HIGH", "priority": "alert" }],
            "drillDownAction": "ora.Invoke(\"viewIssue\", { \"id\": \"ISS-301\" })",
            "action": { "text": "Assign", "command": "ora.Invoke(\"assignIssue\", { \"id\": \"ISS-301\" })" }
        },
        {
            "cells": ["ISS-302", "Slow dashboard", { "type": "badge", "text": "MEDIUM", "priority": "warning" }],
            "drillDownAction": "ora.Invoke(\"viewIssue\", { \"id\": \"ISS-302\" })",
            "action": { "text": "Assign", "command": "ora.Invoke(\"assignIssue\", { \"id\": \"ISS-302\" })" }
        }
    ]
}

// Example 5: Multi-select table with submit metadata
{
    "id": "selected_orders",
    "subtitle": "Orders awaiting batch approval",
    "selectMode": "multiSelect",
    "multiSelectActionText": "Approve Selected",
    "multiSelectMetadata": {
        "action": "approve_orders",
        "source": "batch_review_queue"
    },
    "cols": ["Order ID", "Customer", "Status"],
    "rows": [
        {
            "cells": ["ORD-5001", "Acme Corp", { "type": "badge", "text": "PENDING", "priority": "warning" }]
        },
        {
            "cells": ["ORD-5002", "Global Inc", { "type": "badge", "text": "PENDING", "priority": "warning" }]
        }
    ]
}
    </examples>
</multiRecordWidget>


<cardWidget>
    <description>The card shows important singular alerts or messages that give status on a specific item of interest.</description>
    <schema>
{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "required": ["subject", "summary"],
    "properties": {
        "subject": {
            "type": "string",
